//! The spell-engine `#[reducer]`s — the scheduled aura tick (`tick_auras`), the one-shot pending-cast
//! completion (`fire_pending_cast`), and the player-facing `cast_spell`. `mod.rs` re-exports these so
//! the reducer registry + `crate::spell::<reducer>` paths resolve.

use spacetimedb::{log, reducer, ReducerContext, ScheduleAt, Table, TimeDuration, Timestamp};

// The `game_world_entity` accessor trait (generated by the table macro in world.rs) must be in scope to
// read/write the live unit row by guid (the periodic tick's health/power writes); `WorldEntity` is the row
// type, named by the `flush_pool` field-setter below.
use crate::{game_world_entity, WorldEntity};
// Tables, the cast core (`begin_cast`/`resolve_cast_at`), the math helpers, and the control predicates
// are all re-exported by `mod.rs`.
use super::*;

/// One-shot scheduler callback: a `PendingCast` whose cast time elapsed — resolve the deferred effect.
/// Scheduler-only; ignores `resolve_cast_at`'s `Err` (the caster may have died / the GCD may now reject
/// by the time the cast finishes) — logged, never panics. The scheduler auto-deletes the one-shot row.
#[reducer]
pub fn fire_pending_cast(ctx: &ReducerContext, sched: PendingCast) {
    if ctx.sender() != ctx.database_identity() {
        return;
    }
    let result = resolve_cast_at(
        ctx,
        sched.caster_guid,
        sched.spell_id,
        sched.level,
        sched.target_guid,
        // is_completion=true marks this as the TIMED cast finishing its bar (vs a genuine instant cast). The
        // relay (subscriptions.rs on_cast) USES it: a timed completion sends GO ALONE (the begin already sent
        // START(cast_time)); only a genuine instant (is_completion=false) sends the START(0)+GO pair. A 2nd
        // START(0) at completion reset the cast bar to zero-length ("stuck on full") — the cast-lock bug.
        true,
        // NOT client-initiated (088): the completion GO must reach the caster via the relay — the
        // synchronous send only covered the instant CMSG path, never a timed completion.
        false,
        // The clicked ground point carried across the cast bar (118 phase 2): a timed ground-AoE
        // (Flamestrike) anchors its patch here at COMPLETION. `has_dest` false → None (every normal cast).
        sched
            .has_dest
            .then_some((sched.dest_x, sched.dest_y, sched.dest_z)),
    );
    clear_dead_callback_cast_admission(ctx, sched.caster_guid, sched.spell_id);
    if let Err(e) = result {
        log::info!(
            "pending cast {} (spell {}, caster {}) did not resolve: {}",
            sched.scheduled_id,
            sched.spell_id,
            sched.caster_guid,
            e
        );
        // The timed cast failed at COMPLETION (target out of range / gone / dead / not enough power).
        // No SMSG_SPELL_GO will come, so the client's filled cast bar would hang ("stuck on full"). Emit an
        // is_interrupted signal → the gateway relays SMSG_SPELL_FAILURE to the caster, tearing the bar down.
        ctx.db.game_spell_cast_event().insert(SpellCastEvent {
            is_interrupted: true,
            ..SpellCastEvent::signal(ctx, sched.caster_guid, sched.spell_id)
        });
    }
}

/// One-shot scheduler callback: a projectile's missile travel time elapsed — apply the
/// already-resolved (crit+resist-scaled) damage NOW, via the same `apply_target_damage` the instant path
/// uses (absorb/kill/threat/combat-enter all fold identically), then insert the floating damage-log signal
/// on the DEDICATED `game_spell_impact_event` table (never `game_spell_cast_event` — that would replay
/// `SMSG_SPELL_GO`/`SMSG_SPELL_START` through the untouched `on_cast` relay for a cast that already visually
/// resolved at cast time). Always inserts (even a 0-damage row, e.g. a target that died/left the world
/// before impact, or a fully-absorbed hit) — mirrors `resolve_cast_at`'s own cast-GO row, which likewise
/// always inserts and lets the RELAY gate on `damage > 0` (see `on_impact`, subscriptions.rs). Scheduler-only.
#[reducer]
pub fn fire_spell_impact(ctx: &ReducerContext, sched: PendingSpellImpact) {
    if ctx.sender() != ctx.database_identity() {
        return;
    }
    let (dealt, absorbed) = apply_target_damage(
        ctx,
        sched.target_guid,
        sched.caster_guid,
        sched.after_resist,
        // The bolt keeps the origin it was launched with across its travel time, so a proc's own bolt
        // still raises no proc event when it lands.
        crate::combat::Hit::spell(
            if sched.triggered {
                crate::combat::HitSource::Triggered
            } else {
                crate::combat::HitSource::Spell
            },
            sched.spell_id,
            sched.is_crit,
        ),
    );
    // perf catalog 2.3: AOI address of the actor, so this row is delivered to the observers whose box
    // contains them instead of to every connected session. ONE grid_of lookup (was 4 — one per field).
    let (map_id, instance_id, grid_x, grid_y) = crate::helpers::grid_of(ctx, sched.caster_guid);
    ctx.db.game_spell_impact_event().insert(SpellImpactEvent {
        id: 0,
        caster_guid: sched.caster_guid,
        target_guid: sched.target_guid,
        spell_id: sched.spell_id,
        created_at: ctx.timestamp,
        damage: dealt,
        school: sched.school_index,
        is_crit: sched.is_crit,
        resisted: sched.resisted,
        absorbed,
        map_id,
        instance_id,
        grid_x,
        grid_y,
    });
}

/// The spellbook-gated cast core, actor-explicit: everything [`cast_spell`] does after
/// resolving WHO is casting — the sender reducer above and `gw::gw_cast_spell` both delegate here.
/// Distinct from [`crate::actor::cast_at`], which drives `resolve_cast_at` and skips the spellbook
/// gate; this is the player-shaped entry (cast-time aware, self-cast on `target_guid == 0`).
pub(crate) fn do_cast_spell(
    ctx: &ReducerContext,
    caster: crate::WorldEntity,
    spell_id: u32,
    target_guid: u64,
) -> Result<(), String> {
    // Spellbook gate: a player may only cast a spell in its game_player_spell rows (creation grants
    // the createinfo kit; talents/trainers/quests append). Without this a modified client could cast
    // ANY seeded spell (e.g. a Warrior casting Fireball, or another class's ability).
    // (Player-only — creatures cast via the tick straight into `resolve_cast_at`, not this reducer.)
    if !knows_spell(ctx, caster.guid, spell_id) {
        return Err(format!("spell {spell_id} is not in the caster's spellbook"));
    }
    let target = if target_guid == 0 {
        caster.guid
    } else {
        target_guid
    };
    begin_cast(
        ctx,
        caster.guid,
        spell_id,
        caster.level as u8,
        target,
        true,
        None,
    )
}

/// The shared core behind [`cast_spell_at`] and its gateway twin `gw_cast_at` — the
/// ground-target cast with the spellbook, NaN and self-target-default gates.
pub(crate) fn apply_cast_spell_at(
    ctx: &ReducerContext,
    caster: &crate::WorldEntity,
    spell_id: u32,
    target_guid: u64,
    x: f32,
    y: f32,
    z: f32,
) -> Result<(), String> {
    if !knows_spell(ctx, caster.guid, spell_id) {
        return Err(format!("spell {spell_id} is not in the caster's spellbook"));
    }
    // Reject a non-finite click (a malformed/hostile packet) before it becomes a NaN ground area that the
    // distance scan can never match. Mirrors the movement NaN/Inf coord guard (reducer-validation sweep).
    if !(x.is_finite() && y.is_finite() && z.is_finite()) {
        return Err(format!(
            "cast_spell_at: non-finite ground point ({x},{y},{z})"
        ));
    }
    let target = if target_guid == 0 {
        caster.guid
    } else {
        target_guid
    };
    begin_cast(
        ctx,
        caster.guid,
        spell_id,
        caster.level as u8,
        target,
        true,
        Some((x, y, z)),
    )
}

/// Answer a pending resurrect offer by explicit `target_guid` — the shared core `resurrect_response`
/// (caller-authorized) and `debug_resurrect_response` (explicit-guid, CLI identity owns no entity) both
/// drive, mirroring the `do_repop`/`world::do_repop` split. The row is consumed (deleted) either way —
/// accept or decline — so a stale offer never lingers to be replayed. `accept = false` (decline) is a
/// clean no-op deletion; vanilla's CMSG_RESURRECT_RESPONSE carries no separate "expired" status the
/// client distinguishes, so decline and timeout are indistinguishable here (both just drop the row). On
/// accept: revive the target IN PLACE at the offer's frozen `points`% (via `revive_amount`) + clear
/// dead/ghost — a no-op if the target somehow isn't dead anymore (e.g. already reclaimed their corpse
/// while the offer was outstanding).
pub(crate) fn do_resurrect_response(
    ctx: &ReducerContext,
    target_guid: u64,
    accept: bool,
) -> Result<(), String> {
    let requests = ctx.db.game_resurrect_request();
    let req = requests
        .target_guid()
        .find(target_guid)
        .ok_or_else(|| "no pending resurrect offer".to_string())?;
    requests.target_guid().delete(target_guid);
    if accept {
        if let Some(mut t) = ctx.db.game_world_entity().guid().find(target_guid) {
            if t.dead {
                let pct = req.points.clamp(1, 100) as u32;
                t.health = revive_amount(t.max_health, req.points);
                t.power = t.max_power.saturating_mul(pct) / 100;
                t.dead = false;
                t.player_flags &= !lyracore_shared::constants::player_flags::GHOST;
                t.unit_bytes_1 &= !lyracore_shared::constants::unit_vis_flags::GHOST;
                ctx.db.game_world_entity().guid().update(t);
            }
        }
    }
    Ok(())
}

/// The cancel-cast core, actor-explicit — same split as [`do_cast_spell`].
pub(crate) fn do_cancel_cast(
    ctx: &ReducerContext,
    caster: crate::WorldEntity,
) -> Result<(), String> {
    interrupt_cast(ctx, caster.guid);
    break_channel(ctx, caster.guid);
    // Un-queue a pending on-next-swing strike too (114): the vanilla client cancels a queued Heroic
    // Strike (pressing its lit button again) with the same CMSG_CANCEL_CAST. No refund — matches the
    // charge-up-front rule in the E_NEXT_SWING handler. No-op when nothing is queued.
    if caster.next_swing_spell != 0 {
        let mut c = caster;
        c.next_swing_spell = 0;
        ctx.db.game_world_entity().guid().update(c);
    }
    Ok(())
}

/// The cancel-aura core, actor-explicit — same split as [`do_cast_spell`], keyed by guid
/// (the body never reads another column off the row).
pub(crate) fn do_cancel_aura(
    ctx: &ReducerContext,
    player_guid: u64,
    spell_id: u32,
) -> Result<(), String> {
    // PASSIVE spells (talent passives) are server-enforced and NOT player-cancelable — refuse to strip
    // them even if a modified client sends CMSG_CANCEL_AURA, so a player can't right-click off a talent
    // bonus. NEGATIVE auras (debuffs, CC) are likewise refused: the vanilla client never offers
    // cancel on a debuff, so only a modified client sends it — honoring it would let a player strip
    // their own Polymorph/Fear and would ALSO dodge the DR-window stamp that only the real removal
    // paths (expiry/dispel/break-on-damage) apply (192 review finding #2). A non-passive,
    // non-negative (or unknown) spell falls through to the normal cancel.
    if let Some(spell) = ctx.db.game_spell().spell_id().find(spell_id) {
        if spell.attributes & SPELL_ATTR_PASSIVE != 0 {
            return Err(format!(
                "spell {spell_id} is passive and cannot be cancelled"
            ));
        }
        if spell.is_negative {
            return Err(format!(
                "spell {spell_id} is a debuff and cannot be cancelled"
            ));
        }
    }
    let auras = ctx.db.game_aura();
    // Snapshot the matching aura ids (+ whether each moves a vitals pool) before deleting — never
    // mutate the table mid-iteration.
    let to_remove: Vec<(u64, bool, bool, bool)> = auras
        .by_target()
        .filter(&player_guid)
        .filter(|a| a.spell_id == spell_id)
        .map(|a| {
            (
                a.id,
                aura_moves_vitals(a.eff_kind, a.eff_p0),
                crate::spell::aura_moves_sheet(a.eff_kind, a.eff_p0),
                crate::mount::mount_aura_moves_mount(a.eff_kind, a.eff_p0),
            )
        })
        .collect();
    if to_remove.is_empty() {
        return Err(format!("no cancelable aura {spell_id} on the caller"));
    }
    let mut revitalize = false;
    let mut resheet = false;
    let mut remount = false;
    for (id, moves_vitals, moves_sheet, moves_mount) in to_remove {
        auras.id().delete(id);
        revitalize |= moves_vitals;
        resheet |= moves_sheet;
        remount |= moves_mount;
    }
    if revitalize {
        recompute_vitals(ctx, player_guid);
    }
    // Same wider gate as the apply site (targeting.rs) — AFTER vitals so a lost STA/INT aura's
    // sheet recompute sees the already-updated `e.spirit`.
    if resheet {
        recompute_sheet(ctx, player_guid);
    }
    // Right-clicking the mount buff off (`CMSG_CANCEL_AURA`) is an ordinary aura removal — the same
    // collect-then-recompute shape clears the mount display, and the mounted-speed row is already gone
    // with it because both effects share this spell id.
    if remount {
        crate::mount::recompute_mount(ctx, player_guid);
    }
    Ok(())
}

/// Is `expires_at` due to be reaped by NATURAL EXPIRY at `now`? Two rules, both preserved byte-for-byte
/// from the pre-232 `auras.iter().filter(|a| a.expires_at <= now && a.eff_kind != A_STEALTH)` full scan:
/// (1) the boundary is INCLUSIVE (`<=`, not `<`) — an aura expiring at EXACTLY `now` reaps this tick, the
/// mirror of the periodic pass's own inclusive `>=` final-tick boundary just below (a 3s/1s DoT ticks 3×,
/// not 2×, then reaps on that same tick); (2) `A_STEALTH` is a permanent-until-broken PRESENCE (vanilla
/// Stealth has no duration timer) and is NEVER timer-reaped regardless of its `expires_at` — only
/// `break_stealth` removes it. A talent/toggle's `duration_ms == u32::MAX` sentinel (see `aura_apply`)
/// pins `expires_at` to `Timestamp(i64::MAX)`, so this is `false` for any realistic `now` regardless of
/// kind — the permanent-aura case is handled generically by the timestamp compare, not a special case
/// here. Pure — extracted so the boundary + kind-exclusion semantics are unit-tested without a
/// `ReducerContext` (the module crate has no reducer test harness by design; see `tests.rs`).
pub(crate) fn is_due_for_expiry(eff_kind: u8, expires_at: Timestamp, now: Timestamp) -> bool {
    expires_at <= now && eff_kind != A_STEALTH
}

/// The aura tick (scheduled, scheduler-only). Two passes: (1) PERIODIC — every still-active aura that
/// is due (`period_ms > 0` and `now >= next_tick_at`) applies its FROZEN per-tick effect (DoT subtracts
/// via `damaged_value` floored-at-1 — NO kill this spike; HoT adds via `healed_value` clamped; ENERGIZE
/// restores power via `energized_value` clamped to `max_power`, on a separate fold so it never clobbers
/// a same-tick health write) reading ONLY the aura row (no template re-join), then advances its
/// `next_tick_at` by `period_ms` so each aura ticks on its own cadence; (2) EXPIRY — delete auras past
/// `expires_at`. Periodic runs FIRST so a final tick lands on the tick it expires. Collect-then-mutate
/// throughout.
///
/// Work-item 229 (per-instance ticks): DELIBERATELY LEFT GLOBAL — one schedule row, no `instance_id`
/// scoping. Verified: this tick outer-loops `game_aura`, whose rows are per-TARGET and purely
/// due-TIME driven (`next_tick_micros`/`expires_at`); each row touches only its own target's
/// entity/aura state, so there are no cross-instance reads to scope away and the cost is O(active
/// auras) — it scales with buffs/DoTs in flight, NOT with instance count. Per-instance aura cadence
/// would also change DoT/HoT tick RATES (a gameplay change, not smoothing) — out of scope.
#[reducer]
pub fn tick_auras(ctx: &ReducerContext, _schedule: AuraSchedule) {
    if ctx.sender() != ctx.database_identity() {
        return;
    }
    let now = ctx.timestamp;
    let now_micros = now.to_micros_since_unix_epoch();
    let auras = ctx.db.game_aura();
    let entities = ctx.db.game_world_entity();

    // --- Periodic pass: collect the due ticks (snapshot owned aura rows), fold per-target health, then
    // flush the entity writes, then advance each due aura's next_tick — never write a table mid-iter. ---
    // Perf catalog 1.9 — the same recipe work-item 232 used for the expiry pass below, on the SAME
    // table: `by_next_tick` is a btree over the very column being compared, so `.filter(1..=now_micros)`
    // walks only rows that are actually DUE. The `0` sentinel (non-periodic: buffs, passives, stealth
    // presences — the overwhelming majority of rows) is excluded by starting the range at 1, so it needs
    // no data migration; `expires_at`/`period_ms` stay as cheap post-filters on the small candidate set.
    let mut due: Vec<Aura> = auras
        .by_next_tick()
        .filter(1..=now_micros)
        .filter(|a| {
            // `>= now` (not `>`): an aura due to tick at the EXACT moment it expires still gets its final
            // tick — the periodic pass runs before the expiry pass deletes it (a 3s/1s DoT ticks 3×, not 2×).
            a.expires_at >= now && a.period_ms > 0
        })
        .collect();
    // The old full scan visited rows in PK order; the index visits them in due-time order. Two DoTs from
    // different casters landing on the same target in the SAME tick fold against a shared running health,
    // so the order decides who gets the killing-blow credit — restore PK order and the outcome is
    // byte-identical to the pre-index behavior. `due` is O(ticks actually due), so the sort is free.
    due.sort_unstable_by_key(|a| a.id);

    // Fold stacked DoTs/HoTs on the same target against the latest in-tick health, and (separately)
    // stacked A_PERIODIC_ENERGIZE ticks against the latest in-tick power — POWER is a distinct field, so
    // it folds + flushes on its own track (a unit can take a DoT and a periodic energize on the same
    // tick without one clobbering the other's entity write).
    // Per-target running accumulators: health (DoT/HoT) and power (energize), each folded against the
    // latest in-tick value. A HashMap is the natural fit — `insert` overwrites, so `get` always reads the
    // latest value for a target (last-write-wins semantics, O(1) lookup) and it dedupes for free, so the
    // flush below needs no per-target `written` set.
    let mut pending: std::collections::HashMap<u64, u32> = std::collections::HashMap::new();
    let mut pending_power: std::collections::HashMap<u64, u32> = std::collections::HashMap::new();
    // Targets that took real DoT damage this tick — their break-on-damage CC is dropped at the END of the
    // tick (the vanilla "don't DoT the sheep"). Deferred so a broken aura is never re-advanced/double-deleted.
    let mut dot_damaged: std::collections::HashSet<u64> = std::collections::HashSet::new();
    // Creatures a DoT tick KILLS this tick → guid + the killing caster (a player, for XP/loot credit). The
    // periodic path floors at 1 hp, so without this tracking a mob finished purely by DoT ticks would
    // freeze at 1 hp until a direct hit landed. Collected during the fold, finished by kill_creature after
    // the health flush.
    let mut dying: std::collections::HashMap<u64, Option<u64>> = std::collections::HashMap::new();
    // Active Duels a periodic tick finishes. Health folds to one first; centralized completion then
    // removes authorization and combat exactly once after the entity flush.
    let mut finishing_duels: std::collections::HashSet<u64> = std::collections::HashSet::new();
    let mut duel_losers: std::collections::HashSet<u64> = std::collections::HashSet::new();
    let mut duel_finishes: Vec<(u64, u64, u64)> = Vec::new();
    // CHANNEL ticks to FIRE this tick (caster, per-tick trigger spell, frozen cast level, channel target) and
    // channel auras to END early (their PK). Both are deferred to AFTER the fold flush + the cadence advance,
    // so a trigger that kills its target — or an ended channel — never corrupts the in-flight fold/advance.
    let mut channel_fires: Vec<(u64, u32, u8, u64)> = Vec::new();
    let mut channel_end: Vec<u64> = Vec::new();
    for a in &due {
        let Some(target) = entities.guid().find(a.target_guid) else {
            continue;
        };
        if target.dead {
            continue;
        }
        match a.eff_kind {
            A_PERIODIC_DAMAGE => {
                let caster = entities.guid().find(a.caster_guid);
                if caster
                    .as_ref()
                    .is_some_and(|caster| !crate::combat::may_harm(ctx, caster, &target))
                {
                    continue;
                }
                let active_duel =
                    crate::duel::active_duel_between(ctx, a.caster_guid, a.target_guid);
                if active_duel
                    .as_ref()
                    .is_some_and(|duel| finishing_duels.contains(&duel.id))
                {
                    continue;
                }
                // A creature already marked dying this tick (a prior lethal DoT tick on it) takes no more
                // ticks — no double-kill; its `pending` was dropped so the flush can't revive it.
                if dying.contains_key(&a.target_guid) {
                    continue;
                }
                let cur = pending
                    .get(&a.target_guid)
                    .copied()
                    .unwrap_or(target.health);
                // Magic resistance softens DoT ticks too — re-derived per tick from the DoT spell's school +
                // the cast level FROZEN on the aura (`a.level`). No resist aura / physical DoT / missing header
                // → `a.amount` unchanged (baseline-safe).
                let school = ctx
                    .db
                    .game_spell()
                    .spell_id()
                    .find(a.spell_id)
                    .map(|s| s.school_mask)
                    .unwrap_or(0);
                let amount =
                    resist_magic_damage(ctx, a.target_guid, school, a.level as u32, a.amount);
                if amount > 0 {
                    dot_damaged.insert(a.target_guid); // real DoT damage → breaks break-on-damage CC
                                                       // DoT THREAT: a player's DoT tick accrues threat on the creature (the per-tick twin of
                                                       // apply_target_damage's direct-damage threat). Player→creature only.
                    if !target.is_player()
                        && entities
                            .guid()
                            .find(a.caster_guid)
                            .map(|c| c.is_player())
                            .unwrap_or(false)
                    {
                        crate::threat::add_threat(
                            ctx,
                            a.target_guid,
                            a.caster_guid,
                            crate::threat::threat_from_damage(amount as u32), // amount > 0 in this branch
                        );
                    }
                }
                // A DoT tick can land a KILLING BLOW on a CREATURE. The periodic path floors at 1 hp, so
                // without this tracking a mob finished purely by Corruption/Immolate/Rend/SW:Pain/Moonfire
                // ticks would freeze at 1 hp until a direct hit. When the accumulated in-tick damage reaches
                // the creature's health, mark it dying — credited to this DoT's caster if a PLAYER (XP/loot)
                // — and drop its `pending` so the flush writes no floored value; the post-flush kill_creature
                // finishes it (corpse + loot + decay — the shared kill path, identical to a direct/melee
                // killing blow). PLAYERS still floor at 1 (no spell-death of players yet — mirrors
                // apply_target_damage).
                if target.is_player() && amount > 0 && (amount as u32) >= cur {
                    if let Some(duel) = active_duel {
                        pending.insert(a.target_guid, 1);
                        finishing_duels.insert(duel.id);
                        duel_losers.insert(a.target_guid);
                        duel_finishes.push((duel.id, a.caster_guid, a.target_guid));
                    } else {
                        pending.insert(a.target_guid, damaged_value(cur, amount));
                    }
                } else if !target.is_player() && amount > 0 && (amount as u32) >= cur {
                    // A Lethal Damage Floor holds the creature at one health here exactly as it does
                    // on the swing and direct-spell paths: a DoT tick must not be the one resolver
                    // that can end a script the floor exists to keep open.
                    if crate::combat::lethal_floor_protects(ctx, a.target_guid) {
                        pending.insert(a.target_guid, 1);
                        crate::combat::commit_death_prevention(ctx, a.target_guid, a.caster_guid);
                    } else {
                        let killer = entities
                            .guid()
                            .find(a.caster_guid)
                            .filter(|c| c.is_player())
                            .map(|_| a.caster_guid);
                        dying.insert(a.target_guid, killer);
                        pending.remove(&a.target_guid);
                    }
                } else {
                    pending.insert(a.target_guid, damaged_value(cur, amount));
                }
            }
            A_PERIODIC_HEAL => {
                if dying.contains_key(&a.target_guid) || duel_losers.contains(&a.target_guid) {
                    continue; // a terminal damage fold is not revived before its completion runs
                }
                let cur = pending
                    .get(&a.target_guid)
                    .copied()
                    .unwrap_or(target.health);
                let new_health = healed_value(cur, target.max_health, a.amount);
                pending.insert(a.target_guid, new_health);
                // HoT THREAT: a player-cast periodic heal accrues the same 0.5×-split heal threat as a
                // direct heal (add_heal_threat internally no-ops for a non-player healer / zero effective
                // heal / no engaged creature), mirroring apply_heal's direct-heal threat call.
                let effective = new_health.saturating_sub(cur);
                crate::threat::add_heal_threat(ctx, a.caster_guid, a.target_guid, effective);
            }
            A_PERIODIC_ENERGIZE => {
                let cur = pending_power
                    .get(&a.target_guid)
                    .copied()
                    .unwrap_or(target.power);
                pending_power.insert(
                    a.target_guid,
                    energized_value(cur, target.max_power, a.amount),
                );
                // An `enters_combat`-flagged periodic energize (Bloodrage's trickle) refreshes combat so
                // the resource doesn't decay during the buff window — data-driven, no spell id.
                if a.enters_combat {
                    crate::combat::enter_combat(ctx, a.caster_guid);
                }
            }
            A_PERIODIC_TRIGGER => {
                // CHANNEL tick (Arcane Missiles): a self-aura on the caster (here `target` IS the caster —
                // T_SELF) that fires its frozen per-tick missile (`eff_p1`, e.g. 7268) at the FROZEN
                // `channel_target` each tick. END the channel EARLY (delete the aura, no fire) when the
                // caster can't act (stun/poly/fear — `is_action_blocked` reads the caster's CC) or the
                // channel target is gone / dead — vanilla "the channel stops when you're CC'd / the victim
                // dies". Otherwise QUEUE the fire (run AFTER the advance loop). Move / new-cast breaks are
                // handled at their own call sites via `break_channel`; this arm covers CC + target-death.
                let target_alive = entities
                    .guid()
                    .find(a.channel_target)
                    .map(|t| !t.dead)
                    .unwrap_or(false);
                if is_action_blocked(ctx, a.caster_guid) || !target_alive {
                    channel_end.push(a.id);
                } else {
                    channel_fires.push((a.caster_guid, a.eff_p1 as u32, a.level, a.channel_target));
                }
            }
            _ => {} // non-health/power periodic kinds — no entity field to fold this spike
        }
    }
    // Flush each target's folded HEALTH, then its folded POWER — once apiece (the maps are already
    // deduped). Health first, then power, so a target that took both keeps the just-written health: each
    // row is re-read fresh inside `flush_pool` and only the one field is touched.
    flush_pool(ctx, &pending, |e, v| e.health = v);
    flush_pool(ctx, &pending_power, |e, v| e.power = v);
    for (duel_id, winner_guid, loser_guid) in duel_finishes {
        crate::duel::complete_duel(
            ctx,
            duel_id,
            crate::duel::duel_completion_kind::WON,
            winner_guid,
            loser_guid,
        );
    }
    // Finish the creatures a DoT tick brought to 0 this tick — the SHARED kill path (corpse + loot +
    // decay + XP credited to the DoT's caster), identical to a direct spell/melee killing blow. After the
    // health flush so surviving targets keep their folded health; dying guids were dropped from `pending`.
    for (guid, killer) in &dying {
        crate::combat::kill_creature(ctx, *guid, *killer);
    }
    // Death and Duel completion can remove due auras. Advance only surviving rows and preserve
    // any other fields those completion paths changed.
    for a in due {
        let Some(mut a2) = auras.id().find(a.id) else {
            continue;
        };
        a2.next_tick_micros += (a2.period_ms as i64) * 1000;
        auras.id().update(a2);
    }

    // END the channels that broke this tick (caster CC'd / target dead) — AFTER the advance so the deleted
    // row supersedes its just-advanced cadence (no re-fire). A no-op without an A_PERIODIC_TRIGGER channel.
    // No mount recompute here: `channel_end` only ever collects A_PERIODIC_TRIGGER ids (see the arm
    // that fills it), and deleting one removes that row alone — never a mount aura or its sibling.
    for id in channel_end {
        auras.id().delete(id);
    }
    // FIRE each live channel's per-tick missile — AFTER the fold flush + advance, so a bolt that kills its
    // target (routing through `resolve_cast_at` → the missile's E_DAMAGE → the full crit/resist/threat/kill
    // pipeline) can't corrupt the in-flight fold. The trigger reuses the channel caster + the frozen cast
    // level; its own GCD/cost/range/faction gates apply. A rejected fire (dead/out-of-range/CC'd target) is
    // logged, never panics — mirrors `fire_pending_cast`. (The channel aura itself reaps on its own duration
    // via the expiry pass below: N ticks = duration_ms / period_ms.)
    for (caster_guid, trigger_spell, level, channel_target) in channel_fires {
        if trigger_spell == 0 {
            continue; // a channel with no frozen trigger spell is inert (defensive)
        }
        // A channel's per-tick missile resolves immediately (NOT a timed-cast completion) → instant packet
        // sequence (START(0)+GO+COOLDOWN), so is_completion=false.
        if let Err(e) = resolve_cast_at(
            ctx,
            caster_guid,
            trigger_spell,
            level,
            channel_target,
            false,
            false,
            None,
        ) {
            log::info!(
                "channel tick: caster {caster_guid}'s trigger {trigger_spell} at {channel_target} did not resolve: {e}"
            );
        }
    }

    // --- Expiry pass (after periodic). ---
    // Snapshot the expiring auras (id + whether each moves a vitals pool + its target), so that after
    // deleting them we can re-derive max-health/mana for any target that LOST an A_MOD_STAT(STA/INT)
    // aura — a dropped +STA buff must lower the max back down (clamping current). De-dupe the targets so
    // a unit losing several STA/INT auras on the same tick recomputes once.
    // A_STEALTH is a permanent-until-broken PRESENCE (vanilla Stealth has no duration timer) — never
    // timer-reap it; it is removed only by `break_stealth` (the unit acts). Scoped to the KIND, not to
    // duration_ms==0: many spells carry duration_ms==0 from an approximate DBC duration remap (e.g. Rend's
    // DoT), so "duration 0" does NOT mean permanent — only this kind does. Every other aura reaps on its
    // own timer.
    //
    // Work-item 232: this used to be `auras.iter().filter(|a| a.expires_at <= now && ...)` — a full
    // `game_aura` table scan every heartbeat (every 1s, per `AuraSchedule`'s interval), even though the
    // overwhelming majority of rows aren't anywhere near expiry (long buffs, permanent presences, a busy
    // raid's worth of other players' auras). `by_expiry` (tables.rs) is a btree index on the SAME
    // `expires_at` column already being compared, so `.filter(..=now)` walks the index from its low end
    // and stops at the horizon — it visits only rows AT OR PAST expiry, never the untouched tail. The
    // A_STEALTH exclusion is kept as a cheap post-filter on that already-small candidate set (identical
    // combined predicate, same result set, order of the two conditions doesn't matter for a filter).
    let expired: Vec<Aura> = auras
        .by_expiry()
        .filter(..=now)
        .filter(|a| is_due_for_expiry(a.eff_kind, a.expires_at, now))
        .collect();
    // Evidence (work-item 232): the index scan's candidate count vs the table's total row count.
    // `Table::count()` reads datastore metadata (O(1) — no scan), so logging it costs nothing extra; the
    // gap between the two numbers is the rows the OLD full-scan touched that this pass no longer does.
    // `log::debug!` (not `info!`) so a normal RUST_LOG=info run stays silent; enable `RUST_LOG=debug` (or
    // grep a captured run) to see e.g. "expiry scan visited 2 of 4000 aura rows" on a loaded server.
    log::debug!(
        "tick_auras: expiry index scan visited {} of {} total aura rows",
        expired.len(),
        auras.count()
    );
    let mut revitalize: Vec<u64> = Vec::new();
    // Same expiry snapshot, wider gate — a reaped Battle Shout (or a STR/AGI/SPI stat aura) must
    // pull the sheet numbers back down too, even though it never touched a vitals pool.
    let mut resheet: Vec<u64> = Vec::new();
    // A mount aura reaping on its own timer must leave the same end state as right-clicking the buff
    // off: the display cleared and the mounted-speed row gone (story 29). Same snapshot, same
    // de-duped-target shape.
    let mut remount: Vec<u64> = Vec::new();
    for a in &expired {
        if aura_moves_vitals(a.eff_kind, a.eff_p0) && !revitalize.contains(&a.target_guid) {
            revitalize.push(a.target_guid);
        }
        if crate::spell::aura_moves_sheet(a.eff_kind, a.eff_p0) && !resheet.contains(&a.target_guid)
        {
            resheet.push(a.target_guid);
        }
        if crate::mount::mount_aura_moves_mount(a.eff_kind, a.eff_p0)
            && !remount.contains(&a.target_guid)
        {
            remount.push(a.target_guid);
        }
    }
    // CC diminishing returns (work-item 192): a NATURAL EXPIRY is one of the two REMOVAL events that starts
    // the 15s DR window (the other is a dispel — `effects::dispel_target`). `dr_category_for_effect` is a
    // no-op for a non-CC aura / a creature target, so this only touches the handful of player CC rows.
    // Runs BEFORE the delete loop below (order doesn't matter — `game_dr_state` is a separate table — but
    // reads the still-live `expired` snapshot either way).
    for a in &expired {
        if let Some(category) = crate::spell::stacking::dr_category_for_effect(
            ctx,
            a.eff_kind,
            a.eff_p0_kind,
            a.eff_p0,
            a.target_guid,
        ) {
            crate::spell::stacking::dr_window_on_removal(ctx, a.target_guid, category, now_micros);
        }
    }
    for a in &expired {
        auras.id().delete(a.id);
    }
    // Recompute AFTER the deletes so `stat_bonus` no longer counts the reaped auras (the max falls,
    // current clamps down). A target with no STA/INT aura never enters `revitalize`, so this is a no-op
    // for the common case (baseline-safe).
    for target_guid in revitalize {
        recompute_vitals(ctx, target_guid);
    }
    // AFTER vitals, same rationale as the apply/cancel sites — a reaped STA/INT aura's sheet recompute
    // must see the already-updated `e.spirit`.
    for target_guid in resheet {
        recompute_sheet(ctx, target_guid);
    }
    // The mount projection, re-derived from whatever auras survived the reap. A target that lost no
    // mount aura never enters `remount`, so this is a no-op for the common case.
    for target_guid in remount {
        crate::mount::recompute_mount(ctx, target_guid);
    }

    // Break-on-damage from DoTs (LAST — after the next_tick advance + expiry, so a broken aura is never
    // re-advanced or double-deleted): every target that took real periodic damage this tick drops its
    // break-on-damage CC, the same as a melee swing / direct spell. No-op without such an aura.
    for target_guid in dot_damaged {
        // attacker_guid 0: a DoT tick is not a melee swing, so it never provokes Retaliation. Periodic
        // procs are out of scope, so a tick runs no proc pass either.
        break_auras_on_damage(ctx, target_guid, 0, true); // periodic: breaks CC, does NOT interrupt casts
    }
}

/// Flush a per-target accumulator pool (`guid -> folded value`) to live entity rows, setting ONE field via
/// `set`. Each row is re-read fresh, so flushing the health pool before the power pool lets a target that
/// took both keep its just-written health (only the named field is touched). Shared by the periodic tick's
/// health + power flush.
fn flush_pool(
    ctx: &ReducerContext,
    pool: &std::collections::HashMap<u64, u32>,
    set: impl Fn(&mut WorldEntity, u32),
) {
    let entities = ctx.db.game_world_entity();
    for (&guid, &value) in pool {
        if let Some(mut target) = entities.guid().find(guid) {
            set(&mut target, value);
            entities.guid().update(target);
        }
    }
}

/// GROUND-AoE damage tick (118): the twin of `tick_auras`' periodic pass, but keyed on a fixed WORLD
/// POSITION instead of a unit. Each due `game_ground_area` re-scans its radius (live — a mob that walks
/// in mid-duration is hit; one that leaves simply isn't in the next scan, no per-unit aura bookkeeping)
/// and applies one tick of `amount` `school` damage to every HOSTILE inside via the shared
/// apply_resistance→apply_target_damage path (threat / engage / kill_creature / absorb / break-CC all
/// reused). Expired areas are reaped. Isolated from `tick_auras` so a bug here can't roll back the
/// DoT/HoT/channel system. Collect-then-mutate: snapshot the due rows, damage, THEN advance/reap — never
/// write the table mid-iter.
#[reducer]
pub fn tick_ground_areas(ctx: &ReducerContext, _schedule: GroundAreaSchedule) {
    if ctx.sender() != ctx.database_identity() {
        return;
    }
    // Deliberate simplification: global AoE cap per area — a ground patch can't damage more than
    // this many units per tick (mirrors cast.rs AOE_MAX_TARGETS; a ground area over a huge pull
    // just caps, never scans away).
    const AOE_MAX_TARGETS: usize = 20;
    let now = ctx.timestamp;
    let now_micros = now.to_micros_since_unix_epoch();
    let areas = ctx.db.game_ground_area();
    let entities = ctx.db.game_world_entity();

    // Snapshot: collect the due, mark the finished for reaping (never mutate the table mid-scan).
    // A tick FIRES if it was SCHEDULED within the area's lifetime (`next_tick <= expires`) and is now
    // due. The lifetime gate is `next_tick` vs `expires` — BOTH cast-relative + exact — NOT the wall
    // clock (`expires < now`): a coarse 500ms poll almost always fires just PAST the exact expiry
    // instant, so reaping on `expires < now` before ticking would drop the FINAL tick every time
    // (Consecration would deal 7 ticks, not 8). This deterministic gate lands all `duration/period`
    // ticks regardless of poll phase; the reap only fires once no in-lifetime tick remains
    // (`next_tick > expires`, i.e. after the last tick advanced it). Since the 500ms poll evenly
    // divides the 1s/2s tick periods, each area's ticks land on a REGULAR cadence offset by a constant
    // ≤500ms — not per-tick drift. A server hitch just catches up one tick per poll (never dropped).
    let mut expired: Vec<u64> = Vec::new();
    let mut due: Vec<GroundArea> = Vec::new();
    for a in areas.iter() {
        let expires_micros = a.expires_at.to_micros_since_unix_epoch();
        match classify_ground_tick(a.next_tick_micros, a.period_ms, expires_micros, now_micros) {
            GroundTickStatus::Fire => due.push(a),
            GroundTickStatus::Reap => expired.push(a.id),
            GroundTickStatus::Wait => {}
        }
    }
    for id in expired {
        areas.id().delete(id);
        // Reap the area's client-visible swirl in lockstep — the delete relays SMSG_DESTROY_OBJECT.
        ctx.db
            .game_dynamic_object()
            .guid()
            .delete(crate::spell::cast::dynamic_object_guid(id));
    }

    for a in &due {
        // Live radius scan: hostile, alive, same map/instance, in radius, NOT the caster. Reuses the same
        // squared-distance + faction idiom as select_targets' T_AREA_ENEMY fan-out.
        let caster = entities.guid().find(a.caster_guid);
        let r2 = a.radius_yd * a.radius_yd;
        // Grid-indexed scan (by_grid btree, scoped to the cells covering the radius) — the scale-safe
        // replacement for a full game_world_entity iteration, so a Consecration over a busy zone costs
        // O(nearby entities), not O(whole world). `entities_near` already filters map/instance + returns a
        // whole-cell SUPERSET, so we keep the exact squared-distance check + the alive/caster/faction gates.
        let targets: Vec<u64> =
            crate::helpers::entities_near(ctx, a.map_id, a.instance_id, a.x, a.y, a.radius_yd)
                .into_iter()
                .filter(|c| !c.dead && c.guid != a.caster_guid)
                .filter_map(|c| {
                    let (dx, dy, dz) = (c.x - a.x, c.y - a.y, c.z - a.z);
                    if dx * dx + dy * dy + dz * dz > r2 {
                        return None;
                    }
                    caster
                        .as_ref()
                        .is_some_and(|caster| crate::combat::is_hostile_target(ctx, caster, &c))
                        .then_some(c.guid)
                })
                .take(AOE_MAX_TARGETS)
                .collect();

        for t in targets {
            // Magic resist first (the caster's level drives mitigation; a gone caster → 0% = full damage),
            // then the shared damage entry point (threat / engage / kill_creature / absorb / combat-flag).
            let resisted = apply_resistance(ctx, t, a.caster_guid, a.school_mask, a.amount);
            // A ground-area tick is nobody's swing and nobody's cast — Triggered, so it raises no
            // proc event.
            let (dealt, absorbed) = apply_target_damage(
                ctx,
                t,
                a.caster_guid,
                resisted,
                crate::combat::Hit::triggered(),
            );
            // Per-tick feedback (118, user: area damage "does not show on damage numbers or in the
            // combat log"): a log-only cast-event row (`is_proc_log`, same shape as the seal's holy
            // line) — the gateway relays ONLY the SMSG_SPELLNONMELEEDAMAGELOG named after the area's
            // spell ("Consecration hits X for N Holy"), never START/GO. Emitted for a landed OR
            // fully-absorbed tick (absorb suffixes render); a 0/0 tick (target vanished) logs nothing.
            if dealt > 0 || absorbed > 0 {
                ctx.db
                    .game_spell_cast_event()
                    .insert(crate::spell::SpellCastEvent {
                        target_guid: t,
                        damage: dealt,
                        school: crate::spell::school_index(a.school_mask),
                        resisted: (a.amount.max(0) as u32).saturating_sub(resisted.max(0) as u32),
                        absorbed,
                        is_proc_log: true,
                        ..crate::spell::SpellCastEvent::signal(ctx, a.caster_guid, a.spell_id)
                    });
            }
        }
    }

    // Advance each due area's cadence by one period (re-fetch fresh: damage above may have deleted
    // entities but never the area row; the fresh find guards a since-expired/removed area).
    for a in &due {
        if let Some(mut fresh) = areas.id().find(a.id) {
            fresh.next_tick_micros += (fresh.period_ms as i64) * 1000;
            areas.id().update(fresh);
        }
    }

    // Perf catalog 1.20: DISARM when there is nothing left to tick. `game_ground_area` is empty on
    // any server that isn't mid-Consecration/Flamestrike — which is nearly always — and a permanent
    // 500ms interval row costs 2 transactions/s of pure scheduling overhead on the serialized writer
    // forever. `arm_ground_area_tick` re-inserts the row at the ONE place areas are born, so the
    // system is demand-driven like `PendingCast`/`PendingSpellImpact` already are.
    if areas.count() == 0 {
        let schedules = ctx.db.game_ground_area_schedule();
        let ids: Vec<u64> = schedules.iter().map(|s| s.scheduled_id).collect();
        for id in ids {
            schedules.scheduled_id().delete(id);
        }
    }
}

/// Ensure the 500ms `tick_ground_areas` schedule row exists — called wherever a `game_ground_area`
/// row is BORN (perf catalog 1.20's disarm deletes it whenever the area table drains). Idempotent and
/// cheap: the table holds 0 or 1 rows. Must stay in lockstep with the interval in `seed::init` /
/// `debug_repair_after_publish` (formerly the standalone `debug_ensure_ground_area_schedule`).
pub(crate) fn arm_ground_area_tick(ctx: &ReducerContext) {
    if ctx.db.game_ground_area_schedule().count() > 0 {
        return;
    }
    ctx.db
        .game_ground_area_schedule()
        .insert(GroundAreaSchedule {
            scheduled_id: 0,
            scheduled_at: ScheduleAt::Interval(TimeDuration::from_micros(500_000)),
        });
}

#[derive(PartialEq, Debug)]
pub(crate) enum GroundTickStatus {
    /// Due now AND scheduled within the area's lifetime — deal this tick.
    Fire,
    /// No in-lifetime tick remains (`next_tick` past `expires`, or unset) — reap the row.
    Reap,
    /// Has a future in-lifetime tick, not yet due — leave it.
    Wait,
}

/// Pure tick-lifetime decision for one ground area. The lifetime gate is `next_tick <= expires`
/// (both cast-relative + exact) — NOT the wall clock — so a coarse poll that lands just past the
/// exact expiry still fires the final scheduled tick instead of reaping it. See the caller comment.
pub(crate) fn classify_ground_tick(
    next_tick_micros: i64,
    period_ms: u32,
    expires_micros: i64,
    now_micros: i64,
) -> GroundTickStatus {
    if period_ms > 0
        && next_tick_micros != 0
        && now_micros >= next_tick_micros
        && next_tick_micros <= expires_micros
    {
        GroundTickStatus::Fire
    } else if next_tick_micros == 0 || next_tick_micros > expires_micros {
        GroundTickStatus::Reap
    } else {
        GroundTickStatus::Wait
    }
}

#[cfg(test)]
mod duel_periodic_wiring_tests {
    #[test]
    fn periodic_damage_rechecks_authorization_and_finishes_at_one_health() {
        let body = crate::test_scan::code_of(include_str!("scheduler.rs"), "pub fn tick_auras(");
        assert!(body.contains("crate::combat::may_harm"));
        assert!(body.contains("crate::duel::active_duel_between"));
        assert!(body.contains("pending.insert(a.target_guid, 1)"));
        assert!(body.contains("crate::duel::complete_duel"));
    }

    /// The periodic fold is the one damage resolver that cannot route through `final_damage`: it
    /// folds several auras against an in-transaction health the durable row does not carry yet. It
    /// must still consult the floor before marking a creature dying, or a DoT tick becomes the only
    /// way to kill a creature a script is holding at one health.
    #[test]
    fn a_periodic_kill_consults_the_lethal_damage_floor_before_marking_a_creature_dying() {
        let body = crate::test_scan::code_of(include_str!("scheduler.rs"), "pub fn tick_auras(");
        let protects = body
            .find("crate::combat::lethal_floor_protects(ctx, a.target_guid)")
            .expect("the periodic creature-kill branch no longer consults the lethal floor");
        let dying = body
            .find("dying.insert(a.target_guid, killer)")
            .expect("the periodic creature-kill branch no longer marks a creature dying");
        assert!(
            protects < dying,
            "the floor must be consulted BEFORE the creature is marked dying"
        );
        assert!(body.contains("crate::combat::commit_death_prevention"));
    }
}

#[cfg(test)]
mod ground_tick_tests {
    use super::*;

    /// Drive one area from cast to reap at a fixed poll cadence starting at `phase` micros past cast,
    /// counting how many ticks fire. Mirrors the reducer: on Fire, advance next_tick by one period.
    fn simulate(period_ms: u32, duration_ms: u32, poll_ms: i64, phase_us: i64) -> u32 {
        let period_us = period_ms as i64 * 1000;
        let expires = duration_ms as i64 * 1000; // cast at t=0
        let mut next_tick = period_us; // create_ground_area seeds cast + one period
        let mut fires = 0u32;
        let mut now = phase_us;
        loop {
            match classify_ground_tick(next_tick, period_ms, expires, now) {
                GroundTickStatus::Fire => {
                    fires += 1;
                    next_tick += period_us;
                }
                GroundTickStatus::Reap => break,
                GroundTickStatus::Wait => now += poll_ms * 1000,
            }
        }
        fires
    }

    #[test]
    fn every_scheduled_tick_fires_regardless_of_poll_phase() {
        // Consecration: 8×1s ticks over 8s. Must be exactly 8 no matter where the 500ms poll lands
        // relative to the exact tick instants — this is the final-tick reap bug the fix closed.
        for phase_us in [0, 1, 250_000, 499_999, 500_000, 750_000] {
            assert_eq!(
                simulate(1000, 8000, 500, phase_us),
                8,
                "phase {phase_us}us dropped/added a tick",
            );
        }
    }

    #[test]
    fn coarser_poll_than_period_still_lands_all_ticks() {
        // Poll (500ms) evenly dividing a 2s period, and the degenerate case where the poll is
        // COARSER than the period (700ms poll, 500ms period) — catch-up, never drop.
        assert_eq!(simulate(2000, 8000, 500, 123_000), 4);
        assert_eq!(simulate(500, 8000, 700, 40_000), 16);
    }

    #[test]
    fn classify_boundaries() {
        // next_tick exactly at expiry → still fires (<=, not <).
        assert_eq!(
            classify_ground_tick(8000, 1000, 8000, 8000),
            GroundTickStatus::Fire
        );
        // one micro past expiry → reap.
        assert_eq!(
            classify_ground_tick(8001, 1000, 8000, 9000),
            GroundTickStatus::Reap
        );
        // due-time in the future, still within lifetime → wait.
        assert_eq!(
            classify_ground_tick(2000, 1000, 8000, 1500),
            GroundTickStatus::Wait
        );
        // unset next_tick / zero period → reap (never scheduled).
        assert_eq!(
            classify_ground_tick(0, 1000, 8000, 5000),
            GroundTickStatus::Reap
        );
    }
}
